import React, { useState, useEffect, useRef } from 'react';
import { Card, api } from '../App';

export default function ReportsPage() {
  const [saleNos,      setSaleNos]      = useState([]);
  const [selSale,      setSelSale]      = useState('');
  const [activeTab,    setActiveTab]    = useState('party');
  const [partyData,    setPartyData]    = useState([]);
  const [expanded,     setExpanded]     = useState(null);
  const [loadingParty, setLoadingParty] = useState(false);
  const [marketData,   setMarketData]   = useState([]);
  const [mktGrade,     setMktGrade]     = useState('');
  const [loadingMkt,   setLoadingMkt]   = useState(false);
  const printRef = useRef(null);

  useEffect(() => {
    api.get('/import/sale-numbers')
      .then(r => { setSaleNos(r.data); if (r.data[0]) setSelSale(String(r.data[0].sale_no)); })
      .catch(() => {});
  }, []);

  const loadPartyReport = async () => {
    if (!selSale) return;
    setLoadingParty(true);
    try { const r = await api.get(`/reports/party-summary?sale_no=${selSale}`); setPartyData(r.data); }
    catch (e) { alert(e.response?.data?.error || e.message); }
    finally { setLoadingParty(false); }
  };

  const loadMarketReport = async () => {
    if (!selSale) return;
    setLoadingMkt(true);
    try { const r = await api.get(`/reports/market?sale_no=${selSale}`); setMarketData(r.data); }
    catch (e) { alert(e.response?.data?.error || e.message); }
    finally { setLoadingMkt(false); }
  };

  useEffect(() => {
    if (!selSale) return;
    if (activeTab === 'party')  loadPartyReport();
    if (activeTab === 'market') loadMarketReport();
  }, [selSale, activeTab]); // eslint-disable-line

  const grades = [...new Set(marketData.map(r => r.grade))].sort();
  const filteredMarket = mktGrade ? marketData.filter(r => r.grade === mktGrade) : marketData;
  const mktByGrade = {};
  filteredMarket.forEach(row => {
    if (!mktByGrade[row.grade]) mktByGrade[row.grade] = [];
    mktByGrade[row.grade].push(row);
  });

  const downloadPartyPDF = () => {
    const win = window.open('', '_blank');
    const rowsHtml = partyData.map(party => {
      const lotsRows = (party.lots || []).map((lot, i) => `
        <tr style="background:${i%2===0?'#fff':'#f9fafb'}">
          <td>${lot.garden || ''}</td>
          <td>${lot.origin || ''}</td>
          <td><span class="grade">${lot.grade || ''}</span></td>
          <td>${lot.broker || ''}</td>
          <td style="font-family:monospace">${lot.invoice || ''}</td>
          <td>${lot.bags || ''}</td>
          <td>${lot.net_wt || ''}</td>
          <td style="text-align:right;font-weight:bold;color:#1a7a4a">${lot.price ? '\u20B9' + parseFloat(lot.price).toFixed(0) : ''}</td>
        </tr>`).join('');
      return `
        <div class="party-block">
          <div class="party-hdr">
            <span class="pcode">${party.party_code}</span>
            <span class="pname">${party.party_name}</span>
            <span class="plots">${party.total_lots} lots</span>
          </div>
          <table>
            <thead><tr><th>Garden</th><th>Origin</th><th>Grade</th><th>Broker</th><th>Invoice</th><th>Bags</th><th>Net Wt</th><th>Price \u20B9</th></tr></thead>
            <tbody>${lotsRows}</tbody>
          </table>
        </div>`;
    }).join('');

    win.document.write(`<!DOCTYPE html><html><head><title>Party Report - Sale #${selSale}</title>
<style>
  body { font-family: Arial, sans-serif; font-size: 10px; margin: 15mm; color: #1a2533; }
  h1 { font-size: 14px; color: #1a3c5e; margin-bottom: 3px; }
  .party-block { margin-bottom: 10px; page-break-inside: avoid; }
  .party-hdr { background: #1a3c5e; color: #fff; padding: 4px 10px; display: flex; align-items: center; gap: 10px; border-radius: 3px 3px 0 0; }
  .pcode { background: rgba(255,255,255,0.2); padding: 1px 6px; border-radius: 8px; font-weight: 900; font-size: 11px; }
  .pname { font-weight: 700; font-size: 12px; flex: 1; }
  .plots { font-size: 10px; opacity: 0.8; }
  table { width: 100%; border-collapse: collapse; font-size: 9px; border: 1px solid #e2e8f0; }
  th { background: #f0f4f8; padding: 4px 6px; text-align: left; font-weight: 700; color: #444; }
  td { padding: 3px 6px; border-bottom: 1px solid #f0f4f8; }
  .grade { background: #dbeafe; color: #1e40af; padding: 1px 5px; border-radius: 8px; font-weight: 800; font-size: 8px; }
  @page { size: A4; margin: 10mm; }
  @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }
</style></head><body>
<h1>Party Marking Report &mdash; Sale #${selSale}</h1>
<p style="color:#888;font-size:9px;margin-bottom:8px;">Generated: ${new Date().toLocaleString('en-IN')} &nbsp;|&nbsp; ${partyData.length} parties</p>
${rowsHtml}
</body></html>`);
    win.document.close();
    win.focus();
    setTimeout(() => { win.print(); win.close(); }, 500);
  };

  const downloadPDF = () => {
    const content = printRef.current;
    if (!content) return;
    const printWindow = window.open('', '_blank');
    const html = `<!DOCTYPE html>
<html><head><title>Market Report - Sale #${selSale}</title>
<style>
  body { font-family: Arial, sans-serif; font-size: 11px; margin: 20px; color: #1a2533; }
  h1 { font-size: 16px; color: #1a3c5e; }
  h2 { font-size: 13px; color: #1a3c5e; margin: 14px 0 6px; padding: 4px 8px; background: #f0f4f8; }
  table { width: 100%; border-collapse: collapse; margin-bottom: 14px; }
  th { background: #1a3c5e; color: #fff; padding: 5px 8px; text-align: left; font-size: 11px; }
  th.right { text-align: right; }
  td { padding: 4px 8px; border-bottom: 1px solid #e2e8f0; font-size: 11px; }
  td.right { text-align: right; font-weight: bold; }
  tr:nth-child(even) { background: #f8fafc; }
  .low { color: #1a7a4a; }
  .high { color: #c0392b; }
  @media print { body { margin: 8px; } }
</style></head><body>
<h1>Market Price Report &mdash; Sale #${selSale}</h1>
<p style="color:#888;font-size:10px;">Generated: ${new Date().toLocaleString('en-IN')}</p>
${content.innerHTML}
</body></html>`;
    printWindow.document.write(html);
    printWindow.document.close();
    printWindow.focus();
    setTimeout(() => { printWindow.print(); printWindow.close(); }, 600);
  };

  // ── Styles ─────────────────────────────────────────────────────────────────
  const tabBtn = (key) => ({
    padding: '8px 18px', borderRadius: 6, cursor: 'pointer', fontWeight: 600, fontSize: 13, border: 'none',
    background: activeTab === key ? '#1a3c5e' : '#f0f4f8',
    color:      activeTab === key ? '#fff'    : '#555',
  });

  const th = (right) => ({
    padding: '7px 10px', textAlign: right ? 'right' : 'left',
    fontWeight: 700, color: '#444', whiteSpace: 'nowrap',
  });

  const td = (extra) => ({ padding: '6px 10px', ...extra });

  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>📊 Reports</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 16 }}>Party marking report and market price report from sold list.</p>

      {/* Controls */}
      <Card style={{ marginBottom: 16, padding: 14 }}>
        <div style={{ display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap' }}>
          <div>
            <label style={{ fontSize: 11, fontWeight: 700, color: '#555', textTransform: 'uppercase', letterSpacing: 0.4, marginBottom: 4, display: 'block' }}>
              Sale Number
            </label>
            <select value={selSale} onChange={e => setSelSale(e.target.value)}
              style={{ padding: '7px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 200 }}>
              <option value="">Select sale...</option>
              {saleNos.map(s => (
                <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>
              ))}
            </select>
          </div>
          <div style={{ display: 'flex', gap: 8, marginLeft: 'auto' }}>
            <button style={tabBtn('party')}  onClick={() => setActiveTab('party')}>👥 Party Report</button>
            <button style={tabBtn('market')} onClick={() => setActiveTab('market')}>📈 Market Report</button>
          </div>
        </div>
      </Card>

      {/* ── PARTY REPORT ── */}
      {activeTab === 'party' && (
        <Card>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
            <h3 style={{ fontSize: 15 }}>Party Marking Report — Sale #{selSale}</h3>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <span style={{ fontSize: 12, color: '#888' }}>{partyData.length} parties</span>
              {partyData.length > 0 && (
                <button onClick={downloadPartyPDF}
                  style={{ padding: '6px 14px', background: '#1a3c5e', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer', fontWeight: 700, fontSize: 12 }}>
                  📄 Download PDF
                </button>
              )}
            </div>
          </div>

          {loadingParty && <div style={{ padding: 30, textAlign: 'center', color: '#888' }}>⏳ Loading...</div>}

          {!loadingParty && partyData.length === 0 && (
            <div style={{ padding: 30, textAlign: 'center', color: '#aaa' }}>No markings for Sale #{selSale}</div>
          )}

          {!loadingParty && partyData.map(party => {
            const isExp = expanded === party.party_code;
            const rowBg    = isExp ? '#1a3c5e' : '#f8fafc';
            const rowColor = isExp ? '#fff' : '#1a3c5e';
            const badgeBg  = isExp ? 'rgba(255,255,255,0.2)' : '#dbeafe';
            const badgeClr = isExp ? '#fff' : '#1e40af';
            const cntColor = isExp ? '#90cdf4' : '#1a7a4a';

            return (
              <div key={party.party_code} style={{ marginBottom: 8, border: '1.5px solid #e2e8f0', borderRadius: 8, overflow: 'hidden' }}>
                <div onClick={() => setExpanded(isExp ? null : party.party_code)}
                  style={{ padding: '10px 16px', background: rowBg, cursor: 'pointer', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                    <span style={{ background: badgeBg, color: badgeClr, padding: '2px 10px', borderRadius: 99, fontSize: 12, fontWeight: 700 }}>
                      {party.party_code}
                    </span>
                    <span style={{ fontWeight: 700, fontSize: 14, color: rowColor }}>{party.party_name}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                    <span style={{ fontSize: 13, fontWeight: 700, color: cntColor }}>{party.total_lots} lots</span>
                    <span style={{ color: isExp ? '#fff' : '#888', fontSize: 12 }}>{isExp ? '▲' : '▼ Click to view'}</span>
                  </div>
                </div>

                {isExp && (
                  <div style={{ overflowX: 'auto' }}>
                    <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                      <thead>
                        <tr style={{ background: '#f0f4f8' }}>
                          {['Garden (Mark)', 'Origin', 'Grade', 'Broker', 'Invoice', 'Bags', 'Net Wt', 'Price ₹'].map(h => (
                            <th key={h} style={th(h === 'Price ₹')}>{h}</th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {(party.lots || []).map((lot, i) => (
                          <tr key={i} style={{ borderBottom: '1px solid #f0f4f8', background: i % 2 === 0 ? '#fff' : '#fafbfc' }}>
                            <td style={td({ fontWeight: 700, color: '#1a3c5e' })}>{lot.garden}</td>
                            <td style={td({ fontSize: 11, color: '#777' })}>{lot.origin || '—'}</td>
                            <td style={td()}>
                              <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 8px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{lot.grade}</span>
                            </td>
                            <td style={td({ color: '#555' })}>{lot.broker || '—'}</td>
                            <td style={td({ fontFamily: 'monospace', fontSize: 11, color: '#888' })}>{lot.invoice || '—'}</td>
                            <td style={td()}>{lot.bags || '—'}</td>
                            <td style={td()}>{lot.net_wt || '—'}</td>
                            <td style={td({ fontWeight: 600, color: '#1a7a4a', textAlign: 'right' })}>
                              {lot.price ? `₹${parseFloat(lot.price).toFixed(0)}` : '—'}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            );
          })}
        </Card>
      )}

      {/* ── MARKET REPORT ── */}
      {activeTab === 'market' && (
        <Card>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
            <div>
              <h3 style={{ fontSize: 15 }}>Market Price Report — Sale #{selSale}</h3>
              <div style={{ fontSize: 12, color: '#888', marginTop: 2 }}>
                From Sold List — Grade-wise garden prices (Low → High)
              </div>
            </div>
            <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <select value={mktGrade} onChange={e => setMktGrade(e.target.value)}
                style={{ padding: '7px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13 }}>
                <option value="">All Grades</option>
                {grades.map(g => <option key={g} value={g}>{g}</option>)}
              </select>
              <button onClick={downloadPDF}
                style={{ padding: '7px 16px', background: '#1a3c5e', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer', fontWeight: 700, fontSize: 13 }}>
                📄 Download PDF
              </button>
            </div>
          </div>

          {loadingMkt && <div style={{ padding: 30, textAlign: 'center', color: '#888' }}>⏳ Loading...</div>}

          {!loadingMkt && marketData.length === 0 && (
            <div style={{ padding: 30, textAlign: 'center', color: '#aaa' }}>
              No sold list data for Sale #{selSale}. Upload Sold List first.
            </div>
          )}

          {!loadingMkt && marketData.length > 0 && (
            <div ref={printRef}>
              {Object.entries(mktByGrade).map(([grade, rows]) => {
                const prices  = rows.map(r => parseFloat(r.price_low)).filter(n => !isNaN(n) && isFinite(n));
                const gradeMin = prices.length ? Math.min(...prices) : 0;
                const gradeMax = Math.max(...rows.map(r => parseFloat(r.price_high) || 0));
                const sorted   = [...rows].sort((a, b) => parseFloat(a.price_low) - parseFloat(b.price_low));

                return (
                  <div key={grade} style={{ marginBottom: 22 }}>
                    {/* Grade header */}
                    <div style={{ background: '#1a3c5e', color: '#fff', padding: '8px 14px', borderRadius: '8px 8px 0 0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                        <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 10px', borderRadius: 99, fontSize: 13, fontWeight: 700 }}>
                          {grade}
                        </span>
                        <span style={{ fontSize: 12, opacity: 0.8 }}>{rows.length} gardens</span>
                      </div>
                      <div style={{ fontSize: 13, fontWeight: 700 }}>
                        Range: ₹{gradeMin.toFixed(0)} – ₹{gradeMax.toFixed(0)}
                      </div>
                    </div>

                    {/* Grade table — only Garden, Origin, Low, High, Avg */}
                    <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12, border: '1px solid #e2e8f0', borderTop: 'none' }}>
                      <thead>
                        <tr style={{ background: '#f0f4f8' }}>
                          <th style={th(false)}>Garden (Mark)</th>
                          <th style={th(false)}>Origin</th>
                          <th style={th(true)}>Low ₹</th>
                          <th style={th(true)}>High ₹</th>
                        </tr>
                      </thead>
                      <tbody>
                        {sorted.map((row, i) => (
                          <tr key={i} style={{ borderBottom: '1px solid #f0f4f8', background: i % 2 === 0 ? '#fff' : '#fafbfc' }}>
                            <td style={td({ fontWeight: 700, color: '#1a3c5e' })}>{row.garden}</td>
                            <td style={td({ fontSize: 11, color: '#777' })}>{row.origin || '—'}</td>
                            <td style={td({ textAlign: 'right', color: '#1a7a4a', fontWeight: 700 })}>
                              ₹{parseFloat(row.price_low).toFixed(0)}
                            </td>
                            <td style={td({ textAlign: 'right', color: '#c0392b', fontWeight: 700 })}>
                              ₹{parseFloat(row.price_high).toFixed(0)}
                            </td>

                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                );
              })}
            </div>
          )}
        </Card>
      )}
    </div>
  );
}
